<?php
declare(strict_types=1);namespace App\Services\Finance;use App\Models\Bank\BankTransaction;use App\Models\Finance\{StudentInvoice,StudentPayment,StudentVirtualAccount};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;class BriReconciliationService{public function reconcile(BankTransaction $transaction,?int $actor):StudentPayment{return DB::transaction(function()use($transaction,$actor){$transaction=BankTransaction::lockForUpdate()->findOrFail($transaction->id);$existing=StudentPayment::where('bank_reference',$transaction->provider_reference?:$transaction->external_id)->first();if($existing)return $existing;$va=StudentVirtualAccount::where('external_id',$transaction->external_id)->orWhere('virtual_account_number',$transaction->request_reference)->first();if(!$va||!$va->invoice_id)throw ValidationException::withMessages(['transaction'=>'VA atau tagihan tidak ditemukan.']);$invoice=StudentInvoice::lockForUpdate()->findOrFail($va->invoice_id);if((int)$transaction->amount>(int)$invoice->outstanding_amount)throw ValidationException::withMessages(['transaction'=>'Nominal bank tidak sesuai sisa tagihan.']);$payment=app(PaymentService::class)->record($invoice,['amount'=>$transaction->amount,'paid_at'=>$transaction->occurred_at??now(),'payment_method'=>'bri_briva','bank_reference'=>$transaction->provider_reference?:$transaction->external_id,'source'=>'bri_callback'],$actor);$transaction->update(['reconciled_at'=>now(),'status'=>'matched']);return $payment;});}}
